// Package build orchestrates compilation: it discovers Lyth packages in a Go
// module, runs the front end and lowering, validates generated code with
// go/types, writes generated files, and invokes the go command through an
// overlay so the user's source tree is never modified.
package build

import (
	"bufio"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Module describes the Go module being built.
type Module struct {
	Root string // absolute module root directory
	Path string // module path from go.mod
	// Synthetic is set for single-file builds outside a module; Root is then
	// a temporary module created by lyth.
	Synthetic bool
}

// FindModule walks up from dir to the nearest go.mod.
func FindModule(dir string) (*Module, error) {
	abs, err := canonical(dir)
	if err != nil {
		return nil, err
	}
	for d := abs; ; d = filepath.Dir(d) {
		gomod := filepath.Join(d, "go.mod")
		if data, err := os.ReadFile(gomod); err == nil {
			mp := modulePath(string(data))
			if mp == "" {
				return nil, fmt.Errorf("%s: no module directive", gomod)
			}
			return &Module{Root: d, Path: mp}, nil
		}
		if parent := filepath.Dir(d); parent == d {
			return nil, errNoModule
		}
	}
}

var errNoModule = errors.New("no go.mod found")

// canonical returns an absolute path with symlinks resolved, so overlay
// paths match the paths the go command computes (e.g. /var -> /private/var
// on macOS).
func canonical(path string) (string, error) {
	abs, err := filepath.Abs(path)
	if err != nil {
		return "", err
	}
	if real, err := filepath.EvalSymlinks(abs); err == nil {
		return real, nil
	}
	return abs, nil
}

func modulePath(gomod string) string {
	sc := bufio.NewScanner(strings.NewReader(gomod))
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if rest, ok := strings.CutPrefix(line, "module"); ok {
			rest = strings.TrimSpace(rest)
			if i := strings.Index(rest, "//"); i >= 0 {
				rest = strings.TrimSpace(rest[:i])
			}
			return strings.Trim(rest, `"`)
		}
	}
	return ""
}

// pkgDir is a directory containing Lyth files.
type pkgDir struct {
	Dir        string // absolute
	Rel        string // relative to the module root, "." for the root
	ImportPath string
	Files      []string // absolute paths of .lyth files, sorted (tests excluded)
	TestFiles  []string // _test.lyth files, compiled only for tests
	GoFiles    []string // hand-written .go files (mixed packages are not supported yet)
	// Std marks a package of Lyth's standard library (lyth/coll), compiled
	// from the sources in the lyth binary.
	Std bool
	// GoTestFiles are hand-written _test.go files. They may test Lyth code,
	// and only go test compiles them, so they can live beside .lyth files.
	GoTestFiles []string
}

// discover finds all directories under the module root containing .lyth
// files, honoring the go command's rules for ignored directories.
func discover(mod *Module) ([]*pkgDir, error) {
	var out []*pkgDir
	err := filepath.WalkDir(mod.Root, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if !d.IsDir() {
			return nil
		}
		name := d.Name()
		if path != mod.Root {
			if strings.HasPrefix(name, ".") || strings.HasPrefix(name, "_") || name == "testdata" || name == "vendor" {
				return filepath.SkipDir
			}
			if _, err := os.Stat(filepath.Join(path, "go.mod")); err == nil {
				return filepath.SkipDir // nested module
			}
		}
		p, err := scanDir(mod, path)
		if err != nil {
			return err
		}
		if p != nil {
			out = append(out, p)
		}
		return nil
	})
	sort.Slice(out, func(i, j int) bool { return out[i].ImportPath < out[j].ImportPath })
	return out, err
}

func scanDir(mod *Module, dir string) (*pkgDir, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	p := &pkgDir{Dir: dir}
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if strings.HasPrefix(name, ".") || strings.HasPrefix(name, "_") {
			continue
		}
		path := filepath.Join(dir, name)
		switch {
		case strings.HasSuffix(name, "_test.lyth"):
			p.TestFiles = append(p.TestFiles, path)
		case strings.HasSuffix(name, ".lyth"):
			p.Files = append(p.Files, path)
		case strings.HasSuffix(name, ".lyth.go") || strings.HasSuffix(name, ".lyth_test.go"):
			// generated by lyth gen -in-tree
		case strings.HasSuffix(name, "_test.go"):
			p.GoTestFiles = append(p.GoTestFiles, path)
		case strings.HasSuffix(name, ".go"):
			p.GoFiles = append(p.GoFiles, path)
		}
	}
	if len(p.Files) == 0 {
		return nil, nil
	}
	sort.Strings(p.Files)
	sort.Strings(p.TestFiles)
	rel, err := filepath.Rel(mod.Root, dir)
	if err != nil {
		return nil, err
	}
	p.Rel = filepath.ToSlash(rel)
	if p.Rel == "." {
		p.ImportPath = mod.Path
	} else {
		p.ImportPath = mod.Path + "/" + p.Rel
	}
	return p, nil
}

// displayName returns a path relative to the working directory when that is
// shorter, for diagnostics.
func displayName(abs, wd string) string {
	if rel, err := filepath.Rel(wd, abs); err == nil && !strings.HasPrefix(rel, "..") {
		return rel
	}
	return abs
}
